#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_picture_score_three(void) {
    // Setup: capture stdout to verify output
    void* cap = capture_stdout_start();
    TEST_ASSERT_NOT_NULL(cap);

    // Test: call picture with score = 3 to trigger case 3
    picture(3);

    // Stop capture and get output
    char* output = capture_stdout_stop(cap);
    TEST_ASSERT_NOT_NULL(output);

    // Assert: output should contain the expected substring for score 3
    // From implementation: case 3 prints "    < _ )" (without the quotes)
    // The actual string includes newlines and spaces as shown.
    // We'll check for a distinctive substring that appears only in case 3.
    // The substring "< _ )" is unique to cases 3,4,5 but combined with preceding newlines/spaces.
    // The full expected output for score 3 is:
    // "


     < _ ) "
    // We'll check for the presence of "< _ )".
    TEST_ASSERT_NOT_NULL(strstr(output, "< _ )"));

    // Cleanup
    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_picture_score_three);
    return UNITY_END();
}

